import re
import sqlite3


_INSERT_RE = re.compile(r"^\s*INSERT\s+(?:OR\s+IGNORE\s+)?INTO\s+([a-zA-Z_][a-zA-Z0-9_]*)", re.I)
_INSERT_IGNORE_RE = re.compile(r"^(\s*)INSERT\s+OR\s+IGNORE\s+INTO\b", re.I)


def postgres_schema(schema):
    schema = re.sub(r"(?im)^\s*PRAGMA\s+[^;]+;\s*", "", schema)
    schema = re.sub(
        r"\bINTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT\b",
        "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
        schema,
        flags=re.I,
    )
    return re.sub(r"\bINTEGER\b", "BIGINT", schema, flags=re.I)


def _convert_placeholders(query, escape_percent):
    result = []
    quote = None
    index = 0
    while index < len(query):
        char = query[index]
        if char == "%" and escape_percent:
            result.append("%%")
        elif quote:
            result.append(char)
            if char == quote:
                if index + 1 < len(query) and query[index + 1] == quote:
                    result.append(query[index + 1])
                    index += 1
                else:
                    quote = None
        elif char in ("'", '"'):
            quote = char
            result.append(char)
        elif char == "?":
            result.append("%s")
        else:
            result.append(char)
        index += 1
    return "".join(result)


class PostgresCursor:
    def __init__(self, cursor, lastrowid=None, returned_row=None):
        self._cursor = cursor
        self.lastrowid = lastrowid
        self._returned_row = returned_row

    @property
    def rowcount(self):
        return self._cursor.rowcount

    def fetchone(self):
        if self._returned_row is not None:
            row, self._returned_row = self._returned_row, None
            return row
        return self._cursor.fetchone()

    def fetchall(self):
        if self._returned_row is None:
            return self._cursor.fetchall()
        row, self._returned_row = self._returned_row, None
        return [row, *self._cursor.fetchall()]

    def __iter__(self):
        if self._returned_row is not None:
            row, self._returned_row = self._returned_row, None
            yield row
        yield from self._cursor


class PostgresConnection:
    def __init__(self, connection, id_tables):
        self._connection = connection
        self._id_tables = id_tables

    @staticmethod
    def _translate(query, id_tables, returning=True, escape_percent=True):
        ignored_conflict = bool(_INSERT_IGNORE_RE.search(query))
        translated = _INSERT_IGNORE_RE.sub(r"\1INSERT INTO", query)
        match = _INSERT_RE.match(translated)
        table = match.group(1).lower() if match else None
        if ignored_conflict and not re.search(r"\bON\s+CONFLICT\b", translated, re.I):
            translated = translated.rstrip().rstrip(";") + " ON CONFLICT DO NOTHING"
        should_return = (
            returning
            and table in id_tables
            and not re.search(r"\bRETURNING\b", translated, re.I)
        )
        if should_return:
            translated = translated.rstrip().rstrip(";") + " RETURNING id"
        return _convert_placeholders(translated, escape_percent), should_return

    def execute(self, query, args=()):
        translated, should_return = self._translate(
            query, self._id_tables, escape_percent=bool(args)
        )
        cursor = self._connection.execute(translated, args)
        if not should_return:
            return PostgresCursor(cursor)
        row = cursor.fetchone()
        return PostgresCursor(cursor, row["id"] if row else None, row)

    def executemany(self, query, args):
        arguments = list(args)
        translated, _ = self._translate(
            query, self._id_tables, returning=False, escape_percent=bool(arguments)
        )
        return PostgresCursor(self._connection.executemany(translated, arguments))

    def executescript(self, script):
        result = None
        for statement in script.split(";"):
            if statement.strip():
                result = self.execute(statement)
        return result

    def commit(self):
        self._connection.commit()

    def rollback(self):
        self._connection.rollback()

    def close(self):
        self._connection.close()


def connect(database_url, id_tables):
    try:
        import psycopg
        from psycopg.rows import dict_row
    except ImportError as exc:
        raise RuntimeError(
            "PostgreSQL support requires the project dependencies; install them with `pip install -r requirements.txt`."
        ) from exc
    connection = psycopg.connect(database_url, row_factory=dict_row, connect_timeout=10)
    return PostgresConnection(connection, id_tables)


DB_INTEGRITY_ERRORS = (sqlite3.IntegrityError,)
DB_ERRORS = (sqlite3.Error,)
try:
    import psycopg
except ImportError:
    pass
else:
    DB_INTEGRITY_ERRORS += (psycopg.IntegrityError,)
    DB_ERRORS += (psycopg.Error,)
